// Executable differential tests using values GENERATED BY RUNNING pinned GutTS.
// See scripts/generate-upstream-golden.mjs and the immutable testdata snapshot.
#include "gut/portable.hpp"
#include "gut/json.hpp"
#include "gut/net.hpp"
#include "gut/storage_path.hpp"
#include <cmath>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>
#ifndef GUTCPP_GOLDEN_PATH
#error GUTCPP_GOLDEN_PATH must reference the committed pinned upstream fixture
#endif
using namespace gut;
static json_value ints(const std::vector<int>& data){json_value::array a;for(int x:data)a.emplace_back(x);return json_value(std::move(a));}
static json_value nested(const std::vector<std::vector<int>>& data){json_value::array a;for(const auto& v:data)a.push_back(ints(v));return json_value(std::move(a));}
static json_value run(std::string_view id){
  if(id=="arrays.chunk")return nested(chunk<int>({1,2,3,4,5},2));
  if(id=="arrays.compact")return ints(compact<int>({1,std::nullopt,2,std::nullopt,3}));
  if(id=="arrays.unique")return ints(unique<int>({1,2,1,3}));
  if(id=="arrays.flatten")return json_value(flatten_one({json_value::array{1,2},json_value::array{3},4}));
  if(id=="arrays.last")return json_value(*last(std::vector<int>{1,2,3}));
  if(id=="numbers.clamp")return json_value(clamp(-2,0,12));
  if(id=="numbers.inRange")return json_value(in_range(10,0,10));
  if(id=="numbers.roundTo")return json_value(round_to(1.2345,2));
  if(id=="numbers.sum")return json_value(sum({1.25,2.5,-3}));
  if(id=="strings.isBlank")return json_value(is_blank("\xE2\x80\x83 \t"));
  if(id=="strings.startsWithAny")return json_value(starts_with_any("GutCPP",{"Wrong","Gut"}));
  if(id=="strings.endsWithAny")return json_value(ends_with_any("GutCPP",{"JS","CPP"}));
  if(id=="strings.truncateWords")return json_value(truncate_words("  alpha beta gamma delta  ",2));
  if(id=="urls.joinUrl")return json_value(join_url("https://example.com///",{"/a/","//b/",""}));
  if(id=="urls.getQueryParam")return json_value(*get_query_param("https://example.com/path?q=hello+world&q=two","q"));
  if(id=="urls.setQueryParam")return json_value(set_query_param("https://example.com/path?a=1","b","hello world"));
  if(id=="urls.isUrl")return json_value(is_url("https://example.com/path"));
  if(id=="urls.normalizeStoragePath")return json_value(normalize_storage_path("///alpha///beta/file.txt//"));
  if(id=="urls.encodeSafePathSegments")return json_value(encode_safe_path_segments("alpha/file name.txt"));
  if(id=="urls.resolveTrustedApiUrl")return json_value(resolve_trusted_api_url("https://api.example.com","/v1/%2Fproject?x=1"));
  if(id=="json.parseJson")return parse_json("{\"a\":[1,true,null],\"b\":\"hello\"}");
  if(id=="json.stringifyJson")return json_value(stringify_json(parse_json("{\"a\":[1,true,null]}")));
  if(id=="auth.parseIdentityRef"){
    const auto r=parse_identity_ref("application","app-1");
    if(!r)throw std::invalid_argument("Unexpected invalid identity");
    return json_value(json_value::object{{"kind",r->kind},{"id",r->id}});
  }
  if(id=="arrays.chunk.invalid")return nested(chunk<int>({1},0));
  if(id=="strings.truncateWords.invalid")return json_value(truncate_words("alpha beta",-1));
  if(id=="urls.normalizeStoragePath.invalid")return json_value(normalize_storage_path("a/%252e%252e/b"));
  if(id=="urls.resolveTrustedApiUrl.invalid")return json_value(resolve_trusted_api_url("https://api.example.com","//other.example.com"));
  if(id=="json.parseJson.invalid")return parse_json("{");
  throw std::invalid_argument("Unrecognized golden fixture case ID");
}
int main(){
  std::ifstream file(GUTCPP_GOLDEN_PATH,std::ios::binary);
  if(!file){std::cerr<<"Pinned upstream fixture is absent\n";return 1;}
  const std::string content((std::istreambuf_iterator<char>(file)),std::istreambuf_iterator<char>());
  const auto fixture=parse_json(content).as<json_value::object>();
  const auto sha=fixture.at("sourceSha").as<std::string>();
  if(sha!="3e2cbc0990ba29830ce91c5d1a1d552675d5334c")return 1;
  const auto cases=fixture.at("cases").as<json_value::array>();
  if(cases.size()!=28)return 1;
  for(const auto& item:cases){
    const auto& c=item.as<json_value::object>();
    const auto& id=c.at("id").as<std::string>();
    const auto& kind=c.at("kind").as<std::string>();
    bool threw=false;json_value result;
    try{result=run(id);}catch(const std::invalid_argument&){threw=true;}
    if(kind=="error"){
      if(!threw){std::cerr<<"Expected native exception for "<<id<<"\n";return 1;}
    }else if(kind=="value"){
      if(threw||!(result==c.at("value"))){
        std::cerr<<"Pinned GutTS differential failed: "<<id<<"\n";return 1;
      }
    }else{std::cerr<<"Invalid fixture kind for "<<id<<"\n";return 1;}
  }
  return 0;
}
